export async function listTools() {
  return [
    {
      name: 'catalog_search',
      description: 'Search the catalog by name (case-insensitive) with pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search string matched case-insensitively against item names.' },
          offset: { type: 'integer', default: 0, minimum: 0, description: 'Number of results to skip.' },
          limit: { type: 'integer', default: 2, minimum: 1, maximum: 5, description: 'Maximum number of results to return.' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'catalog_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { query, offset = 0, limit = 2 } = args;

  // Validate no extra properties
  const allowed = new Set(['query', 'offset', 'limit']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected argument: ${key}`);
    }
  }

  // Validate query
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }

  // Validate offset
  if (!Number.isInteger(offset) || offset < 0) {
    throw new Error('offset must be a non-negative integer');
  }

  // Validate limit
  if (!Number.isInteger(limit) || limit < 1 || limit > 5) {
    throw new Error('limit must be an integer between 1 and 5');
  }

  const q = query.toLowerCase();
  const matches = items.filter(item => item.name.toLowerCase().includes(q));
  const slice = matches.slice(offset, offset + limit);
  const hasMore = offset + limit < matches.length;
  const result = {
    results: slice,
    count: slice.length,
    offset,
    limit,
    ...(hasMore ? { next_offset: offset + limit } : {})
  };

  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
}
